-- READ-ONLY aggregate; exact-key source rows absent from reconstruction. UTC fixed bounds.
WITH c AS (SELECT CASE WHEN o.dateTime < 1293840000 THEN 2010 ELSE 2011 END AS utc_year, o.usUnits AS ou, w.usUnits AS wu, o.interval AS oi, w.interval AS wi, o.`rainBatteryStatus` AS old_rainBatteryStatus, w.`rainBatteryStatus` AS wh_rainBatteryStatus, o.`rainRate` AS old_rainRate, w.`rainRate` AS wh_rainRate, o.`referenceVoltage` AS old_referenceVoltage, w.`referenceVoltage` AS wh_referenceVoltage, o.`rxCheckPercent` AS old_rxCheckPercent, w.`rxCheckPercent` AS wh_rxCheckPercent, o.`soilMoist1` AS old_soilMoist1, w.`soilMoist1` AS wh_soilMoist1, o.`soilMoist2` AS old_soilMoist2, w.`soilMoist2` AS wh_soilMoist2, o.`soilMoist3` AS old_soilMoist3, w.`soilMoist3` AS wh_soilMoist3, o.`soilMoist4` AS old_soilMoist4, w.`soilMoist4` AS wh_soilMoist4, o.`soilTemp1` AS old_soilTemp1, w.`soilTemp1` AS wh_soilTemp1, o.`soilTemp2` AS old_soilTemp2, w.`soilTemp2` AS wh_soilTemp2
FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime
WHERE o.dateTime >= 1262304000 AND o.dateTime < 1325376000 AND r.dateTime IS NULL)
SELECT utc_year, 'rainBatteryStatus' AS field_name, COUNT(*) AS source_only_rows, SUM(old_rainBatteryStatus IS NOT NULL) AS old_nonnull, SUM(wh_rainBatteryStatus IS NOT NULL) AS wh_nonnull, SUM(old_rainBatteryStatus IS NOT NULL AND wh_rainBatteryStatus IS NOT NULL AND old_rainBatteryStatus <=> wh_rainBatteryStatus) AS paired_equal, SUM(old_rainBatteryStatus IS NOT NULL AND wh_rainBatteryStatus IS NOT NULL AND NOT(old_rainBatteryStatus <=> wh_rainBatteryStatus)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'rainRate' AS field_name, COUNT(*) AS source_only_rows, SUM(old_rainRate IS NOT NULL) AS old_nonnull, SUM(wh_rainRate IS NOT NULL) AS wh_nonnull, SUM(old_rainRate IS NOT NULL AND wh_rainRate IS NOT NULL AND old_rainRate <=> wh_rainRate) AS paired_equal, SUM(old_rainRate IS NOT NULL AND wh_rainRate IS NOT NULL AND NOT(old_rainRate <=> wh_rainRate)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'referenceVoltage' AS field_name, COUNT(*) AS source_only_rows, SUM(old_referenceVoltage IS NOT NULL) AS old_nonnull, SUM(wh_referenceVoltage IS NOT NULL) AS wh_nonnull, SUM(old_referenceVoltage IS NOT NULL AND wh_referenceVoltage IS NOT NULL AND old_referenceVoltage <=> wh_referenceVoltage) AS paired_equal, SUM(old_referenceVoltage IS NOT NULL AND wh_referenceVoltage IS NOT NULL AND NOT(old_referenceVoltage <=> wh_referenceVoltage)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'rxCheckPercent' AS field_name, COUNT(*) AS source_only_rows, SUM(old_rxCheckPercent IS NOT NULL) AS old_nonnull, SUM(wh_rxCheckPercent IS NOT NULL) AS wh_nonnull, SUM(old_rxCheckPercent IS NOT NULL AND wh_rxCheckPercent IS NOT NULL AND old_rxCheckPercent <=> wh_rxCheckPercent) AS paired_equal, SUM(old_rxCheckPercent IS NOT NULL AND wh_rxCheckPercent IS NOT NULL AND NOT(old_rxCheckPercent <=> wh_rxCheckPercent)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilMoist1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilMoist1 IS NOT NULL) AS old_nonnull, SUM(wh_soilMoist1 IS NOT NULL) AS wh_nonnull, SUM(old_soilMoist1 IS NOT NULL AND wh_soilMoist1 IS NOT NULL AND old_soilMoist1 <=> wh_soilMoist1) AS paired_equal, SUM(old_soilMoist1 IS NOT NULL AND wh_soilMoist1 IS NOT NULL AND NOT(old_soilMoist1 <=> wh_soilMoist1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilMoist2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilMoist2 IS NOT NULL) AS old_nonnull, SUM(wh_soilMoist2 IS NOT NULL) AS wh_nonnull, SUM(old_soilMoist2 IS NOT NULL AND wh_soilMoist2 IS NOT NULL AND old_soilMoist2 <=> wh_soilMoist2) AS paired_equal, SUM(old_soilMoist2 IS NOT NULL AND wh_soilMoist2 IS NOT NULL AND NOT(old_soilMoist2 <=> wh_soilMoist2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilMoist3' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilMoist3 IS NOT NULL) AS old_nonnull, SUM(wh_soilMoist3 IS NOT NULL) AS wh_nonnull, SUM(old_soilMoist3 IS NOT NULL AND wh_soilMoist3 IS NOT NULL AND old_soilMoist3 <=> wh_soilMoist3) AS paired_equal, SUM(old_soilMoist3 IS NOT NULL AND wh_soilMoist3 IS NOT NULL AND NOT(old_soilMoist3 <=> wh_soilMoist3)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilMoist4' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilMoist4 IS NOT NULL) AS old_nonnull, SUM(wh_soilMoist4 IS NOT NULL) AS wh_nonnull, SUM(old_soilMoist4 IS NOT NULL AND wh_soilMoist4 IS NOT NULL AND old_soilMoist4 <=> wh_soilMoist4) AS paired_equal, SUM(old_soilMoist4 IS NOT NULL AND wh_soilMoist4 IS NOT NULL AND NOT(old_soilMoist4 <=> wh_soilMoist4)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilTemp1' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilTemp1 IS NOT NULL) AS old_nonnull, SUM(wh_soilTemp1 IS NOT NULL) AS wh_nonnull, SUM(old_soilTemp1 IS NOT NULL AND wh_soilTemp1 IS NOT NULL AND old_soilTemp1 <=> wh_soilTemp1) AS paired_equal, SUM(old_soilTemp1 IS NOT NULL AND wh_soilTemp1 IS NOT NULL AND NOT(old_soilTemp1 <=> wh_soilTemp1)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year UNION ALL
SELECT utc_year, 'soilTemp2' AS field_name, COUNT(*) AS source_only_rows, SUM(old_soilTemp2 IS NOT NULL) AS old_nonnull, SUM(wh_soilTemp2 IS NOT NULL) AS wh_nonnull, SUM(old_soilTemp2 IS NOT NULL AND wh_soilTemp2 IS NOT NULL AND old_soilTemp2 <=> wh_soilTemp2) AS paired_equal, SUM(old_soilTemp2 IS NOT NULL AND wh_soilTemp2 IS NOT NULL AND NOT(old_soilTemp2 <=> wh_soilTemp2)) AS paired_conflict, SUM(ou <> wu) AS unit_conflict_rows, SUM(oi <> wi) AS interval_conflict_rows FROM c GROUP BY utc_year
ORDER BY utc_year, field_name;
